  descriptionLong: "Grok is xAI's conversational AI assistant created by Elon Musk's team with a distinctive personality and real-time knowledge access through the X platform (formerly Twitter). Unlike other AI assistants that adopt a neutral, cautious tone, Grok is designed to be more direct, witty, and willing to tackle controversial topics with less filtering. Its biggest differentiator is real-time awareness — because it has live access to X posts and trends, Grok can discuss current events as they unfold, making it one of the few AI assistants that can comment on breaking news within minutes. For X Premium subscribers (from USD 8 per month via X Premium Plus), Grok is integrated directly into the X interface, available through the sidebar for quick questions about posts, trending topics, or account analysis. The latest Grok-3 model shows competitive performance on coding and math benchmarks, though it trails behind GPT-4 and Claude in general knowledge breadth. For users who want an AI assistant with opinions, real-time news awareness, and less restrictive content policies, Grok offers a genuinely different experience from the safety-first approach of ChatGPT or Claude. The mobile app provides voice interaction and image recognition capabilities. For developers, xAI has released a standalone API with competitive pricing, though the ecosystem is less mature than OpenAI or Anthropic's offerings.",
  descriptionLongZh: "Grok 是 xAI（Elon Musk 团队）开发的对话式 AI 助手，通过 X 平台（原 Twitter）获取实时知识，拥有与众不同的个性。与其他采用中立谨慎语气的 AI 助手不同，Grok 设计得更加直接、机智，愿意以更少的过滤处理有争议的话题。其最大的差异化优势是实时感知能力——由于可以实时访问 X 帖子和趋势，Grok 能够讨论正在发生的事件，是少数能在几分钟内评论突发新闻的 AI 助手之一。对于 X Premium 订阅用户（每月 8 美元起），Grok 直接集成在 X 界面中，通过侧边栏快速回答关于帖子、热门话题或账号分析的问题。最新的 Grok-3 模型在编程和数学基准测试中表现出竞争力，但在通用知识广度上略逊于 GPT-4 和 Claude。对于想要一个有观点、能实时了解新闻、内容限制较少的 AI 助手的用户来说，Grok 提供了与 ChatGPT 或 Claude 安全优先方式截然不同的体验。移动端支持语音交互和图像识别。xAI 已发布独立 API，定价有竞争力，但生态系统不如 OpenAI 或 Anthropic 成熟。",
