    companyZh: "Kaleido",
    founded: "2018",
    headquarters: "Berlin, Germany",
    descriptionLong: "Remove.bg is an AI-powered background removal tool that processes images in seconds with impressive accuracy, even handling complex edges like hair, fur, and transparent objects that traditional chroma key techniques struggle with. Built by the company behind the popular Background Remover API, Remove.bg has become the industry standard for automated background removal used by millions of e-commerce sellers, real estate agents, graphic designers, and photographers. Simply upload an image and the AI automatically detects the foreground subject, creates a precise mask, and delivers a clean cutout with smooth edges ready for compositing onto new backgrounds. The tool offers multiple output options: transparent PNG (most common for product photos and design assets), solid color backgrounds (white/black for e-commerce listings), and blur backgrounds (for portrait photography). Remove.bg also provides an API for automated batch processing — ideal for e-commerce catalogs with hundreds of product photos, real estate listings requiring consistent presentation, or integration into existing workflows via Photoshop and Canva plugins. The free tier handles standard-resolution images, while paid plans starting at USD 10 per month unlock high-resolution output, batch processing, and API access. Compared to manual background removal in Photoshop (which can take 5-10 minutes per image), Remove.bg processes images in 1-5 seconds with quality that rivals professional manual masking for most use cases.",
    descriptionLongZh: "Remove.bg 是一款 AI 驱动的背景移除工具，能在几秒内处理图像，即使面对头发、毛发和透明物体等复杂边缘也能保持令人印象深刻的精度，这是传统色度键技术难以做到的。作为流行的 Background Remover API 背后的公司，Remove.bg 已成为自动化背景移除的行业标准，被数百万电商卖家、房地产经纪人、平面设计师和摄影师使用。只需上传图像，AI 会自动检测前景主体，创建精确蒙版，并输出边缘平滑的干净剪切图，准备合成到新背景上。工具提供多种输出选项：透明 PNG（产品照片和设计资产最常见）、纯色背景（电商列表用白色/黑色）和模糊背景（人像摄影用）。Remove.bg 还提供 API 用于自动化批量处理——非常适合包含数百张产品照片的电商目录、需要一致呈现的房地产列表，或通过 Photoshop 和 Canva 插件集成到现有工作流。免费版处理标准分辨率图像，每月 10 美元起的付费计划解锁高分辨率输出、批量处理和 API 访问。与在 Photoshop 中手动移除背景（每张图片需要 5-10 分钟）相比，Remove.bg 在 1-5 秒内处理图像，质量在大多数使用场景中媲美专业手动蒙版。",
    advantages: ["Fast AI background removal", "Handles complex edges well", "API for automation", "Batch processing"],
