    icon: "\uD83D\uDD8C\uFE0F",
    company: "ClipDrop (Init ML)",
    companyZh: "ClipDrop（Init ML）",
    founded: "2021",
    headquarters: "Paris, France",
    descriptionLong: "ClipDrop is an AI design toolkit developed by Init ML (acquired by Stability AI) that offers a suite of one-click image editing tools for designers and content creators who need fast, high-quality results without launching full design applications. The ClipDrop ecosystem includes image cleanup (remove objects, wires, people from photos), relighting (adjust lighting direction and intensity), background removal (similar to Remove.bg but with additional refinement tools), text-to-image generation powered by Stable Diffusion, upscaling (increase resolution without quality loss), and sketch-to-image (turn rough sketches into detailed renders). What makes ClipDrop practical is its multi-platform availability — it works as a web app, a mobile app (iOS and Android) for on-the-go editing, and integrates with creative tools via API and plugins for Photoshop and Figma. The mobile app is particularly useful for photographers and real estate agents who need to quickly clean up photos in the field. ClipDrop's Cleanup tool is one of the best available, using AI to intelligently fill removed areas with appropriate background content that matches lighting and perspective. Free tier offers basic functionality, while Pro (USD 10 per month) adds higher resolution, API access, and commercial licensing. For quick image fixes where launching Photoshop would be overkill, ClipDrop provides the fastest path from problem to result.",
    descriptionLongZh: "ClipDrop 是 Init ML（后被 Stability AI 收购）开发的 AI 设计工具包，为需要快速高质量结果但无需启动完整设计应用的设计师和内容创作者提供一系列一键式图像编辑工具。ClipDrop 生态包括图像清理（从照片中移除物体、电线、人物）、重新布光（调整光源方向和强度）、背景移除、基于 Stable Diffusion 的文字到图像生成、放大（提高分辨率而不损失质量）以及草图到图像（将粗略草图转化为详细渲染）。ClipDrop 实用的原因在于其多平台可用性——它可作为网页应用、移动端应用（iOS 和 Android）使用，并通过 API 和 Photoshop/Figma 插件与创意工具集成。移动端应用对需要在现场快速清理照片的摄影师和房地产经纪人特别有用。ClipDrop 的清理工具是目前最好的之一，使用 AI 智能地填充删除区域，匹配光照和透视的适当背景内容。免费版提供基本功能，Pro 版（每月 10 美元）增加更高分辨率、API 访问和商业授权。对于启动 Photoshop 显得大材小用的快速图像修复来说，ClipDrop 提供了从问题到结果的最快路径。",
