    name: "CapCut",
    description: "Free all-in-one video editing app with AI features for creators.",
    descriptionZh: "免费的全能视频编辑应用，为创作者提供AI功能。",
    category: "video-generation",
    tags: ["video-editing", "free", "social-media", "mobile"],
    difficulty: "beginner",
    url: "https://capcut.com",
    rating: 4,
    pricing: "Free / Pro $7.99/mo",
    useCase: "CapCut is a free video editor with AI auto-captions, text-to-speech, effects, and templates for social media content.",
    icon: "\uD83C\uDFA5",
    company: "ByteDance",
    companyZh: "字节跳动",
    founded: "2020",
    headquarters: "Beijing, China",
    descriptionLong: "CapCut is a free all-in-one video editing application developed by ByteDance, the company behind TikTok, with powerful AI features that make professional-quality video editing accessible to everyone. Originally created as the official editing tool for TikTok content, CapCut has evolved into a full-featured video editor available on mobile (iOS and Android), desktop (Windows and Mac), and web — with seamless cross-platform project sync. The AI features are where CapCut really shines: auto-captions generate accurate subtitles in multiple languages automatically, text-to-speech converts your text into natural-sounding voiceovers with a variety of voices and accents, motion tracking lets text and effects follow moving objects, and keyframe animation gives you frame-by-frame control for complex animations. CapCut includes an extensive library of effects, transitions, filters, stickers, and licensed music tracks that would cost a fortune in other editors. The auto-cut feature analyzes your footage and removes silences and awkward pauses automatically — a huge time saver for talking-head videos and vlogs. For TikTok and Instagram creators, CapCut offers trending templates that match current platform formats and styles. While the free tier is remarkably generous, CapCut Pro (USD 7.99 per month) removes watermarks, unlocks premium effects, higher export resolutions (4K), and cloud storage. Compared to InVideo, CapCut is more focused on quick social media content creation rather than marketing automation, making it the best choice for individual creators and influencers.",
    descriptionLongZh: "CapCut 是字节跳动（TikTok 母公司）开发的一款免费全能视频编辑应用，其强大的 AI 功能让专业质量的视频编辑对所有人都可访问。最初作为 TikTok 内容的官方编辑工具创建，CapCut 已发展成全功能视频编辑器，支持移动端（iOS 和 Android）、桌面端（Windows 和 Mac）和网页端——具有无缝的跨平台项目同步功能。CapCut 的 AI 功能最为突出：自动字幕以多种语言自动生成准确的标题、文字转语音将文本转换为自然的配音、运动跟踪让文字和效果跟随移动物体、关键帧动画提供逐帧控制实现复杂动画。CapCut 包含丰富的特效、转场、滤镜、贴纸和授权音乐曲目库。自动剪切功能分析你的素材并自动删除静音和尴尬的停顿——对于说话头视频和 vlog 来说是巨大的时间节省。对于 TikTok 和 Instagram 创作者，CapCut 提供与当前平台格式和风格匹配的热门模板。免费版非常慷慨，Pro 版（每月 7.99 美元）去水印、解锁高级特效和更高导出分辨率。与 InVideo 相比，CapCut 更专注于快速的社交媒体内容创作而非营销自动化，是独立创作者和网红的最佳选择。",
    advantages: ["Completely free core features", "AI auto-captions", "Extensive template library", "Desktop and mobile"],
