    founded: "2008",
    headquarters: "Stockholm, Sweden",
    descriptionLong: "Pixlr is a free browser-based photo editing platform that brings professional-grade image editing capabilities to anyone with a web browser, no downloads or installations required. Owned by the 123RF stock photo company, Pixlr offers two main editors: Pixlr X for quick, intuitive edits with a simplified interface, and Pixlr E for advanced users who need layers, masks, blending modes, and precise controls similar to Photoshop. Both work entirely in your browser and save directly to cloud storage or your device. AI-powered features include background removal (one-click subject isolation), generative fill (AI removes objects and fills the space naturally), AI effects (apply artistic styles with a single click), smart filters, and portrait retouching that automatically smooths skin and enhances eyes. Pixlr has also integrated text-to-image generation, letting you create new visuals from descriptions. The free tier is remarkably generous — it includes most core features with ads, while Pixlr Premium (starting at USD 1.99 per month) removes ads, adds advanced tools, larger canvas sizes, and batch processing. For quick edits — resizing social media graphics, removing backgrounds from product photos, adding text overlays — Pixlr is faster and more accessible than installing and launching Photoshop or GIMP. It works on any device including Chromebooks and tablets, making it a solid choice for educators, students, and casual creators.",
    descriptionLongZh: "Pixlr 是一个免费的基于浏览器的照片编辑平台，将专业级的图像编辑能力带给任何拥有网页浏览器的人，无需下载或安装。由 123RF 图库公司拥有，Pixlr 提供两个主要编辑器：Pixlr X 用于快速、直观的编辑，界面简化；Pixlr E 用于需要图层、蒙版、混合模式和类似 Photoshop 的精确控制的高级用户。两者完全在浏览器中运行，直接保存到云存储或本地设备。AI 驱动的功能包括背景移除（一键主体分离）、生成式填充（AI 移除物体并自然填充空间）、AI 效果（一键应用艺术风格）、智能滤镜和自动美化皮肤和眼睛的人像修饰。Pixlr 还集成了文字到图像生成功能。免费版非常慷慨——包含大多数核心功能（带广告），Pixlr Premium（每月 1.99 美元起）去除广告、添加高级工具、更大画布和批量处理。对于快速编辑——调整社交媒体图像大小、移除产品照片背景、添加文字叠加——Pixlr 比安装和启动 Photoshop 或 GIMP 更快更方便。",
