    descriptionLong: "Sourcegraph Cody is an AI coding assistant that stands apart from other tools because it understands your entire codebase — not just the file you're editing, but every repository, every service, every dependency. Powered by Sourcegraph's industry-leading code intelligence platform, Cody provides context-aware answers, autocompletions, and code generation that reference your actual project architecture, API definitions, database schemas, and coding patterns. This makes Cody uniquely valuable for onboarding to large, unfamiliar codebases, refactoring across service boundaries, and understanding complex system behavior. Instead of asking generic AI questions, you ask Cody questions specific to your codebase: \"What does the payment service return when the credit card is declined?\" or \"Find all places where we handle rate limiting\" — and Cody searches across your entire codebase to provide accurate, sourced answers. Cody's autocomplete goes beyond syntax to suggest code that uses your existing functions, follows your project conventions, and integrates with your database schema. The tool integrates into VS Code, JetBrains IDEs, and web-based Sourcegraph search. Cody Free works on public repositories, while Cody Enterprise (custom pricing) unlocks private repository access, custom commands, and organization-wide deployment. For developers working on large, multi-repository projects or joining established codebases, Cody provides the deepest codebase understanding of any AI coding assistant currently available.",
    descriptionLongZh: "Sourcegraph Cody 是一款 AI 编码助手，与其他工具的区别在于它理解你的整个代码库——不仅是你正在编辑的文件，而是每一个仓库、每一个服务、每一个依赖。由 Sourcegraph 行业领先的代码智能平台驱动，Cody 提供上下文感知的答案、自动补全和代码生成，参考你实际的项目架构、API 定义、数据库模式和编码模式。这使得 Cody 在加入大型陌生代码库、跨服务边界重构以及理解复杂系统行为方面具有独特的价值。你不问通用 AI 问题，而是问 Cody 特定于你的代码库的问题——Cody 会搜索整个代码库提供准确的、有来源的答案。Cody 的自动补全超越了语法，建议使用你现有函数的代码，遵循你的项目约定并与你的数据库模式集成。该工具集成到 VS Code、JetBrains IDE 和基于 Web 的 Sourcegraph 搜索中。Cody Free 适用于公共仓库，Cody Enterprise（自定义定价）解锁私有仓库访问和全组织部署。对于在大型多仓库项目上工作或加入既有代码库的开发者来说，Cody 提供了目前任何 AI 编码助手中最深入的代码库理解。",
    advantages: ["Full codebase context", "Code intelligence powered", "Project-aware answers", "Great for codebase onboarding"],
    advantagesZh: ["完整代码库上下文", "代码智能驱动", "项目感知的答案", "适合代码库入职"],
