    icon: "\uD83D\uDC7B",
    company: "Replit",
    companyZh: "Replit",
    founded: "2016",
    headquarters: "San Francisco, CA",
    descriptionLong: "Replit Ghostwriter was the original AI coding assistant built into the Replit browser-based IDE, providing real-time code suggestions, AI chat for coding help, and debugging assistance entirely in the browser with zero setup. Unlike desktop-based AI tools that require local installation, Ghostwriter works anywhere with a browser and internet connection. It offered code completions as you type, an AI chat panel for asking questions about your code, and the ability to generate code from natural language descriptions — all optimized for the Replit environment. Ghostwriter was particularly focused on helping beginners learn to code, with features that explain code in plain language, suggest improvements, and help debug errors step by step. It also supported Replit's unique multi-player mode, allowing multiple users to collaborate with AI assistance simultaneously. While Ghostwriter has been succeeded by the more powerful Replit Agent, it introduced millions of new programmers to AI-assisted coding. Ghostwriter was available across all Replit tiers: free users had limited monthly interactions, while Hacker (USD 20 per month) and Pro (USD 40 per month) subscribers received more generous limits and faster responses. For beginners learning to code and educators teaching programming in a browser-based environment, Ghostwriter provided the most accessible introduction to AI-assisted development. Its legacy lives on in the current Replit AI features.",
    descriptionLongZh: "Replit Ghostwriter 是集成到 Replit 浏览器 IDE 中的原始 AI 编码助手，在浏览器中提供实时代码建议、AI 编码帮助聊天和调试协助，零设置。与需要本地安装的桌面 AI 工具不同，Ghostwriter 只需浏览器和网络连接即可在任何地方工作。它在你输入时提供代码补全、询问代码问题的 AI 聊天面板以及从自然语言描述生成代码的能力——全部针对 Replit 环境优化。Ghostwriter 特别关注帮助初学者学惯了编程，具有用简单语言解释代码、建议改进和逐步帮助调试错误的功能。它还支持 Replit 独特的多玩家模式，允许多个用户同时利用 AI 协作。虽然 Ghostwriter 已被更强大的 Replit Agent 取代，但它将数百万新程序员引入了 AI 辅助编码的世界。Ghostwriter 在所有 Replit 层级上可用：免费用户每月有限次数的交互，Hacker（每月 20 美元）和 Pro（每月 40 美元）订阅者获得更慷慨的限制和更快的响应。对于在浏览器环境中学惯了编程的初学者和教授编程的教育工作者来说，Ghostwriter 提供了最易上手的 AI 辅助开发入门体验。",
