    icon: "\uD83D\uDCE2",
    company: "LibreChat (Community)",
    companyZh: "LibreChat（社区）",
    founded: "2023",
    headquarters: "Open Source",
    descriptionLong: "LibreChat is an open-source chat platform that serves as a unified interface for multiple AI model providers, letting you switch between ChatGPT, Claude, Gemini, and local models in a single conversation. Instead of maintaining separate accounts and browser tabs for each AI service, LibreChat aggregates them into one clean, customizable interface. You bring your own API keys for OpenAI, Anthropic, Google, or any OpenAI-compatible endpoint, and LibreChat handles the rest — including conversation history, preset management, and multi-model chats where you can ask the same question to multiple assistants and compare responses side by side. This makes LibreChat especially valuable for developers and AI enthusiasts who want to evaluate model performance, find the best tool for each task, or build workflows that leverage different models' strengths. Advanced features include conversation branching for exploring alternative responses, custom presets that save system prompts and model parameters, file upload support for analysis, and plugins for extended functionality. As a self-hosted application, LibreChat ensures your conversation data stays under your control, unlike cloud-based alternatives. The active open-source community contributes regular updates, new integrations, and bug fixes. For teams, LibreChat supports multi-user setups with role-based access control. If you regularly use multiple AI tools and want a unified, privacy-respecting interface, LibreChat is the most flexible option available.",
    descriptionLongZh: "LibreChat 是一个开源聊天平台，作为多个 AI 模型提供商的统一界面，让你可以在一次对话中切换 ChatGPT、Claude、Gemini 和本地模型。无需为每个 AI 服务维护单独的账户和浏览器标签页，LibreChat 将它们聚合到一个干净、可定制的界面中。你只需提供自己的 API 密钥（OpenAI、Anthropic、Google 或任何兼容 OpenAI 的端点），LibreChat 处理其余一切——包括对话历史、预设管理和多模型聊天，你可以向多个助手提出相同问题并排比较答案。这使得 LibreChat 对希望评估模型性能、为每个任务找到最佳工具或构建利用不同模型优势的工作流的开发者和 AI 爱好者特别有价值。高级功能包括对话分支、自定义预设、文件上传支持和插件。作为自托管应用，LibreChat 确保你的对话数据掌握在自己手中。活跃的开源社区贡献定期更新和新的集成。如果你经常使用多种 AI 工具并希望有一个统一的、尊重隐私的界面，LibreChat 是最灵活的选择。",
    advantages: ["Multi-provider support", "Self-hosted privacy", "Conversation branching", "Custom presets"],
    advantagesZh: ["多提供商支持", "自托管隐私", "对话分支", "自定义预设"],
