    headquarters: "London, UK",
    descriptionLong: "Stepsize is an AI-powered project management tool specifically designed for engineering teams to track technical debt, manage sprints, and improve code quality. Unlike general project management tools like Jira or Asana that focus on task tracking, Stepsize automatically surfaces technical debt from your codebase by integrating with your version control system and analyzing code changes, pull requests, and issue tracker data. It provides sprint health analysis that shows how technical debt affects velocity, code review insights that identify recurring issues across your team, and automated standup reports generated from actual code activity rather than manual updates. Stepsize AI continuously monitors your codebase for quality issues, architectural problems, and accumulating debt, then prioritizes them alongside feature work so engineering teams can make informed decisions about when to pay down debt versus build new features. Integration with Jira, GitHub, GitLab, and Slack means Stepsize fits into existing workflows without disruption. For engineering managers, Stepsize provides visibility into the true health of their codebase and the productivity impact of quality issues. For individual developers, it highlights areas needing attention and tracks improvement over time. The free tier covers basic tracking for small teams, while Pro (USD 8 per user per month) unlocks full AI insights and integrations.",
    descriptionLongZh: "Stepsize 是一个专门为工程团队设计的 AI 驱动项目管理工具，用于跟踪技术债务、管理迭代和提高代码质量。与 Jira 或 Asana 等专注于任务跟踪的通用项目管理工具不同，Stepsize 通过与版本控制系统集成来分析代码变更、拉取请求和问题跟踪器数据，自动从代码库中检测技术债务。它提供迭代健康分析、代码审查洞察和基于实际代码活动生成的自动站会报告。Stepsize AI 持续监控代码库的质量问题和架构问题，并优先处理它们。与 Jira、GitHub、GitLab 和 Slack 的集成意味着无需额外切换工具。对于工程管理者，Stepsize 提供了代码库真实健康状况的可视性。",
