    founded: "2021",
    headquarters: "San Francisco, CA",
    descriptionLong: "MutableAI is an AI-powered code tool that helps developers with multi-file refactoring, code generation from natural language, documentation, and test creation. Unlike single-file AI coding assistants that only suggest completions within a function, MutableAI understands project context across multiple files, enabling large-scale changes that maintain consistency across your entire codebase. You can describe a change in natural language like \"convert all API endpoints from REST to GraphQL\" or \"add pagination to all list views\" and MutableAI analyzes your project structure, generates the necessary changes across relevant files, and presents them for review. MutableAI excels at cross-cutting concerns where modifications need to happen in many places simultaneously making it particularly useful for refactoring legacy codebases migrating between frameworks or implementing architectural changes. It supports multiple programming languages including TypeScript, Python, Java, Go, and Rust, and integrates with VS Code and JetBrains IDEs. The code generation from natural language produces not just functions but complete file structures including imports, types, error handling, and tests. MutableAI also generates documentation by analyzing existing code and producing JSDoc, type definitions, and README files. Pricing includes a free tier with limited operations, with Pro tiers unlocking unlimited refactoring and team collaboration features.",
    descriptionLongZh: "MutableAI 是一款 AI 驱动的代码工具，帮助开发者进行多文件重构、自然语言代码生成、文档编写和测试创建。与仅在函数内建议补全的单文件 AI 编码助手不同，MutableAI 理解跨多个文件的项目上下文，实现跨整个代码库保持一致的大规模更改。你可以用自然语言描述更改，MutableAI 分析项目结构并在相关文件中生成必要的更改。MutableAI 擅长需要在多个位置同时修改的横切关注点，对于重构遗留代码库、在框架之间迁移或实现架构更改特别有用。它支持 TypeScript、Python、Java、Go 和 Rust 等多种编程语言，并与 VS Code 和 JetBrains IDE 集成。自然语言代码生成不仅生成函数，还生成包括导入、类型、错误处理和测试的完整文件结构。",
