    companyZh: "社区",
    founded: "2022",
    headquarters: "Community",
    descriptionLong: "Stable Diffusion Web UI by AUTOMATIC1111 is the most popular open-source interface for Stable Diffusion image generation, serving as the go-to tool for millions of AI artists, designers, and enthusiasts worldwide. It provides a comprehensive web-based interface for all major Stable Diffusion capabilities: text-to-image generation, image-to-image transformation, inpainting (selectively regenerating parts of an image), outpainting (extending images beyond their original boundaries), upscaling with various algorithms, and batch processing for generating multiple images at scale. What makes AUTOMATIC1111 the dominant Stable Diffusion interface is its extensive extension ecosystem: users can install community-built extensions adding capabilities like ControlNet (guidance using poses edges depth maps), LoRA (efficient fine-tuning for specific styles characters), textual inversion (training new concepts), dynamic prompts (variations with wildcards), and hundreds more. The interface includes detailed parameter controls for sampling methods CFG scale seed and denoising strength allowing fine-grained control over the generation process. It supports all major Stable Diffusion model families including SD 1.5, SDXL, SD 3.5, FLUX, and community fine-tuned models. AUTOMATIC1111 runs locally ensuring privacy and unlimited generations. The main limitation is its GPU memory requirements and the learning curve for mastering all features but for anyone serious about AI image generation the flexibility and power of AUTOMATIC1111 is unmatched by alternatives like ComfyUI or Invoke AI.",
    descriptionLongZh: "AUTOMATIC1111 的 Stable Diffusion Web UI 是最流行的开源 Stable Diffusion 界面，是全球数百万 AI 艺术家、设计师和爱好者的首选工具。它提供全面的基于网页的界面，涵盖文生图、图生图、图像修复、图像扩展、放大和批量处理。其广泛扩展生态系统使其成为主导 Stable Diffusion 界面：用户可以安装 ControlNet、LoRA、文本反转和数百个社区构建的扩展。界面包括详细的参数控制，支持所有主流 Stable Diffusion 模型系列。AUTOMATIC1111 在本地运行，确保隐私和无限生成。主要限制是 GPU 内存要求和掌握所有功能的学习曲线，但对于认真对待 AI 图像生成的人来说，其灵活性和功能是无可比拟的。",
