    founded: "2022",
    headquarters: "Seattle, WA",
    descriptionLong: "Invoke AI is a professional-grade open-source Stable Diffusion toolkit designed for artists and creators who need advanced image generation capabilities beyond what basic web UIs offer. Its most distinctive feature is the unified canvas that supports layers, masks, and blending — much like Photoshop for AI image generation. This allows artists to composite AI-generated elements with manual edits, use inpainting with precision masks, outpainting to extend images beyond their original boundaries, and ControlNet integration for guided generation based on poses, edges, or depth maps. Invoke AI also features a node-based workflow editor similar to ComfyUI for creating complex multi-step generation pipelines. The tool runs locally on your hardware, ensuring complete privacy for sensitive creative work, and supports all major Stable Diffusion model formats including SD 1.5, SDXL, SD 3.5, FLUX, and community LoRAs. Invoke AI workflow is designed for iteration: you generate multiple variations, edit specific parts, adjust parameters, and refine until you achieve the desired result. For professional digital artists, concept designers, and illustrators who need AI as part of a broader creative workflow rather than a standalone generator, Invoke AI provides the most mature and feature-complete open-source solution available. Compared to AUTOMATIC1111 which focuses on parameter exploration, Invoke AI focuses on artistic production with a canvas-first approach.",
    descriptionLongZh: "Invoke AI 是一款专业级的开源 Stable Diffusion 工具包，专为需要超越基础 Web UI 的高级图像生成能力的艺术家和创作者设计。其最突出的特点是支持图层、蒙版和混合的统一画布——就像用于 AI 图像生成的 Photoshop。这使艺术家可以合成 AI 生成元素与手动编辑、使用精确蒙版进行图像修复、扩展图像原始边界、以及基于姿势、边缘或深度图的 ControlNet 指导生成。Invoke AI 还具有类似 ComfyUI 的节点式工作流编辑器。该工具在本地硬件上运行，确保创意工作的完全隐私，支持所有主流 Stable Diffusion 模型格式。对于需要 AI 作为更广泛创意工作流一部分的专业数字艺术家来说，Invoke AI 提供了最成熟、功能最完整的开源解决方案。",
