    icon: "\u{1F4BB}",
    company: "Supermaven Inc.",
    companyZh: "Supermaven",
    founded: "2023",
    headquarters: "San Francisco, CA",
    descriptionLong: "Supermaven is an AI code completion tool designed for speed and large context understanding, positioning itself as a faster alternative to GitHub Copilot with the ability to understand more of your codebase at once. Its key differentiator is a 1 million token context window — far larger than most competing tools — which allows Supermaven to consider your entire project when making suggestions, resulting in completions that are consistent with your overall code architecture, not just the current file. Supermaven achieves this with a custom inference engine optimized for low-latency completions, making it one of the fastest AI code completion tools available. It supports VS Code, JetBrains, and other popular IDEs with features including inline completions, AI chat, and codebase-aware suggestions. The large context window is particularly valuable when working on large files, complex refactoring, or codebases with many interconnected files — scenarios where tools with smaller context windows may suggest inconsistent or irrelevant code. Pricing starts with a free tier for limited completions, with Pro (USD 15 per month) unlocking unlimited completions and the full context window. For developers working with large files or complex codebases who find that other AI completion tools lose context too quickly, Supermaven's massive token window and speed focus offer a compelling alternative, especially for TypeScript, Python, Java, and other language-heavy projects where understanding the full scope matters.",
    descriptionLongZh: "Supermaven 是一款 AI 代码补全工具，专为速度和大型上下文理解设计，作为 GitHub Copilot 的更快替代品，能够一次理解更多的代码库。其关键差异化优势是 100 万 Token 的上下文窗口——远大于大多数竞争工具——这使得 Supermaven 在进行建议时可以考虑整个项目，生成的补全与整体代码架构一致，而不仅仅是当前文件。Supermaven 通过为低延迟补全优化的自定义推理引擎实现这一点，使其成为最快的 AI 代码补全工具之一。它支持 VS Code、JetBrains 和其他流行 IDE，功能包括内联补全、AI 聊天和代码库感知建议。大上下文窗口在处理大文件、复杂重构或有许多相互关联文件的代码库时特别有价值。免费版提供有限的补全次数，Pro 版（每月 15 美元）解锁无限补全和完整上下文窗口。对于使用大型文件或复杂代码库且发现其他 AI 补全工具太快失去上下文的开发者来说，Supermaven 的庞大 Token 窗口和速度优势提供了引人注目的替代方案。",
    targetAudience: "Developers who want fast AI code completions with a large context window for complex codebases.",
