    companyZh: "StackBlitz",
    founded: "2023",
    headquarters: "San Francisco, CA",
    descriptionLong: "Bolt.new by StackBlitz is an AI-powered full-stack app builder that revolutionizes how web applications are created. Instead of writing code yourself, you describe your application idea in natural language, and Bolt.new generates, runs, and deploys a complete full-stack application — including frontend, backend, database, and authentication — in your browser with zero local setup. Bolt.new runs in a browser-based development environment powered by WebContainers (StackBlitz's proprietary technology that runs Node.js entirely in the browser), so everything happens online without installing anything. As you chat with the AI, you can see the app running live in a preview window, make changes by describing them, inspect the generated code, install packages, and push to production — all from a single browser tab. Bolt.new excels at rapid prototyping, MVP development, and hackathon projects where speed matters more than perfect code quality. It generates modern React or Next.js applications with Tailwind CSS styling, responsive layouts, and common backend patterns. The tool supports deploying directly to Netlify or Vercel with a single click. Pricing includes a free tier with limited prompts, with paid plans starting at USD 20 per month for more AI interactions and private projects. Compared to Lovable (formerly GPT Engineer), Bolt.new offers a more complete browser-based development experience that doesn't require connecting to a cloud IDE or local environment — it's the closest thing to having a developer that you can just talk to and get a working app back.",
    descriptionLongZh: "Bolt.new 是 StackBlitz 推出的 AI 全栈应用构建器，彻底改变了 Web 应用的创建方式。你无需自己编写代码，只需用自然语言描述应用创意，Bolt.new 就能在浏览器中生成、运行和部署完整的全栈应用——包括前端、后端、数据库和身份验证——零本地设置。Bolt.new 在由 WebContainers 驱动的基于浏览器的开发环境中运行，所有操作都在线完成，无需安装任何软件。当你与 AI 对话时，可以在预览窗口中实时查看应用运行情况，通过描述进行修改、检查生成的代码、安装包并推送到生产环境——全部在一个浏览器标签页中完成。Bolt.new 擅长快速原型开发、MVP 构建和黑客马拉松项目。它生成带有 Tailwind CSS 样式、响应式布局和常见后端模式的现代 React 或 Next.js 应用。支持一键部署到 Netlify 或 Vercel。免费版提供有限的提示次数，付费计划从每月 20 美元起。与 Lovable 相比，Bolt.new 提供了更完整的基于浏览器的开发体验。",
