    founded: "2023",
    headquarters: "Open Source",
    descriptionLong: "Aider is an open-source AI pair programming tool that operates directly in your terminal with deep Git integration — one of its key differentiators. Unlike most AI coding tools that work inside an editor or IDE, Aider runs as a command-line tool that understands your entire Git repository, reads files it needs, suggests and applies changes, and automatically commits them with sensible commit messages. This tight Git integration means every AI-made change is tracked, reversible, and documented as part of your project history. Aider excels at multi-file edits: it can refactor code across your entire project, adding new features, fixing bugs, or restructuring modules while maintaining coherence across all modified files. The map of your repository gives Aider a high-level understanding of your project structure, helping it decide which files to read and modify for each task. Aider supports all major LLM providers: OpenAI, Anthropic, Google, and local models via Ollama, with Claude (particularly Sonnet and Opus) recommended for complex tasks due to their superior code reasoning. The tool includes a chat interface where you can discuss changes, ask questions about your codebase, and iterate on solutions before applying them. Because Aider is terminal-based, it works with any editor — VS Code, JetBrains, Vim, Emacs — and integrates well with tmux or other terminal multiplexers. For developers who prefer working in the terminal and want AI assistance that respects their Git workflow, Aider provides a seamless, transparent experience where the AI is a true collaborator in the version control process.",
    descriptionLongZh: "Aider 是一款在终端中直接运行的开源 AI 结对编程工具，深度集成 Git——这是其关键差异化优势之一。与大多数在编辑器或 IDE 内部工作的 AI 编码工具不同，Aider 作为命令行工具运行，理解你的整个 Git 仓库，读取需要的文件，建议和应用更改，并自动提交带有合理提交信息的变更。这种紧密的 Git 集成意味着每个 AI 所做的变更都被跟踪、可逆且记录为项目历史的一部分。Aider 擅长多文件编辑：它可以跨整个项目重构代码、添加新功能、修复 bug 或重构模块，同时保持所有修改文件之间的一致性。仓库地图让 Aider 对你的项目结构有高层次的理解，帮助它决定每个任务需要读取和修改哪些文件。Aider 支持所有主要的 LLM 提供商，其中 Claude 因优秀的代码推理能力而被推荐用于复杂任务。由于 Aider 基于终端，它可以与任何编辑器配合使用，并很好地集成到 tmux 中。对于喜欢在终端中工作且希望 AI 辅助尊重 Git 工作流的开发者来说，Aider 提供了一个无缝、透明的体验。",
