    headquarters: "Open Source",
    descriptionLong: "Chroma is an open-source, AI-native vector database that makes it easy to store, manage, and query embeddings for building LLM applications with RAG capabilities. Unlike managed services like Pinecone, Chroma runs embedded in your application or as a standalone server, giving you full control over your data with no vendor lock-in. This makes Chroma the most popular choice for developers who want to experiment with vector search, build privacy-sensitive RAG systems where data cannot leave the infrastructure, or develop applications on a budget without paying per-query costs. Chroma's API is designed to be developer-friendly: you can get started with \"pip install chromadb\" and create a searchable embedding collection in five lines of code. The database supports automatic embedding generation through integration with popular embedding models (OpenAI, Cohere, Hugging Face, Sentence Transformers), metadata filtering, and simple CRUD operations for managing your collections. Chroma is particularly strong in the prototyping and development phase — its simplicity and fast setup make it the go-to choice for hackathons, MVPs, and learning projects. It handles collections of up to millions of embeddings on a single machine, and for larger scale, Chroma supports deployment options with horizontal scaling. The project has an active open-source community contributing plugins and integrations. For developers building RAG applications who value simplicity, transparency, and keeping their data in-house, Chroma provides the most developer-friendly path from prototype to production without the cost and complexity of managed vector database services.",
    descriptionLongZh: "Chroma 是一个开源的 AI 原生向量数据库，用于存储、管理和查询嵌入，方便构建具有 RAG 能力的 LLM 应用。与 Pinecone 等托管服务不同，Chroma 嵌入在你的应用中运行或作为独立服务器运行，让你完全控制数据，无供应商锁定。这使得 Chroma 成为希望尝试向量搜索、构建数据不能离开基础设施的隐私敏感 RAG 系统或在预算内开发应用的开发者的最流行选择。Chroma 的 API 设计为对开发者友好：你可以通过 \"pip install chromadb\" 开始使用，在五行代码中创建一个可搜索的嵌入集合。数据库支持通过集成流行嵌入模型自动生成嵌入、元数据过滤和简单的 CRUD 操作。Chroma 在原型设计和开发阶段特别强大——其简单性和快速设置使其成为黑客马拉松、MVP 和学惯项目的首选。它可以在单台机器上处理多达数百万个嵌入的集合。对于构建重视简单性、透明度和数据本地的 RAG 应用的开发者来说，Chroma 提供了从原型到生产的最开发者友好的路径。",
