    founded: "2009",
    headquarters: "San Francisco, CA",
    descriptionLong: "Cloudflare Workers AI is a serverless AI inference platform that runs on Cloudflare's global GPU network — over 300 locations worldwide — enabling AI model inference at the edge with minimal latency. Unlike traditional AI platforms that route requests to central data centers, Workers AI runs models close to your users, making it ideal for latency-sensitive applications like real-time chatbots, content moderation, translation, and image analysis where response time matters. Workers AI provides access to popular open-source models including Llama 3, Mistral, Phi-4, Gemma, Whisper (speech-to-text), Stable Diffusion, and many more, all available through a simple API integrated with Cloudflare's ecosystem. The platform charges only for compute time used (not per-token), making costs predictable and often lower than dedicated AI API providers for moderate workloads. For developers already using Cloudflare Workers for serverless functions, Workers AI integrates seamlessly — you can build an entire AI application using Workers for logic, KV/R2 for storage, and Workers AI for inference, all within Cloudflare's free tier (limited daily requests). Workers AI also supports fine-tuned models via custom inference, letting you deploy your own trained models on Cloudflare's global network. The key advantage is data locality and compliance: inference runs on Cloudflare's global edge network, so data doesn't leave the region you specify. For developers building AI features who want global low-latency, predictable pricing, and seamless integration with their existing Cloudflare infrastructure, Workers AI provides the most geographically distributed inference platform available.",
    descriptionLongZh: "Cloudflare Workers AI 是一个无服务器 AI 推理平台，运行在 Cloudflare 的全球 GPU 网络上——全球超过 300 个地点——以最小延迟在边缘实现 AI 模型推理。与将请求路由到中央数据中心传统 AI 平台不同，Workers AI 在靠近用户的位置运行模型，使其成为实时聊天机器人、内容审核、翻译和图像分析等对延迟敏感的应用程序的理想选择。Workers AI 提供对流行开源模型的访问，包括 Llama 3、Mistral、Phi-4、Gemma、Whisper、Stable Diffusion 等，全部通过集成在 Cloudflare 生态中的简单 API 使用。平台仅按使用的计算时间收费，使成本可预测且通常低于中等工作负载的专用 AI API 提供商。对于已经在使用 Cloudflare Workers 进行无服务器功能的开发者来说，Workers AI 无缝集成——你可以使用 Workers 处理逻辑、KV/R2 进行存储、Workers AI 进行推理，全部在 Cloudflare 免费版内完成。关键优势是数据本地性和合规性：推理在 Cloudflare 的全球边缘网络上运行，因此数据不会离开你指定的区域。",
