    companyZh: "Nous Research",
    founded: "2024",
    headquarters: "Open Source",
    descriptionLong: "Hermes Agent is an open-source AI agent framework that transforms from a basic conversational assistant into a powerful host system with seven distinct agents working in coordination. Unlike single-agent approaches where one LLM handles everything, Hermes Agent uses a multi-agent architecture where specialized agents focus on different aspects of development: coding, debugging, testing, documentation, deployment, and system administration. The framework operates as a host system that routes requests to the appropriate agents based on task type, with agents capable of collaborating on complex multi-step projects. Hermes Agent supports integration with VPS servers for remote execution, Discord for team communication and command dispatch, a Curator agent for prioritizing and organizing tasks, and real-time monitoring of agent activities. The framework is designed to be extensible — you can add custom agents for your specific needs or modify existing agent behaviors. Hermes Agent works with multiple LLM providers and can use different models for different agents (e.g., a cheaper model for simple tasks and a more capable model for complex reasoning). For developers and teams who want a flexible, multi-agent system that can handle a wide range of development and DevOps tasks autonomously, Hermes Agent offers a proven open-source architecture that scales from personal projects to team environments. The key benefit is parallelism: multiple agents can work on different aspects of a task simultaneously, dramatically reducing time to completion for complex projects.",
    descriptionLongZh: "Hermes Agent 是一个开源 AI 代理框架，从基本对话助手转变为具有七个协调工作的不同代理的强大主机系统。与单个 LLM 处理一切的单一代理方法不同，Hermes Agent 使用多代理架构，专业代理专注于开发的不同方面：编码、调试、测试、文档、部署和系统管理。该框架作为主机系统运行，根据任务类型将请求路由到适当的代理，代理能够协作处理复杂的多步骤项目。Hermes Agent 支持与 VPS 服务器集成进行远程执行、Discord 进行团队通信和命令分发、Curator 代理进行任务的优先级排序和组织，以及代理活动的实时监控。该框架设计为可扩展——你可以为特定需求添加自定义代理或修改现有代理行为。Hermes Agent 可与多个 LLM 提供商配合使用，可以为不同代理使用不同模型。对于想要一个灵活、多代理系统的开发者和团队来说，Hermes Agent 提供了一个成熟的开源架构，可以从个人项目扩展到团队环境。关键优势是并行性：多个代理可以同时处理任务的不同方面，大大减少了复杂项目的完成时间。",
