    icon: "\u{1F399}",
    company: "Vibecoding",
    companyZh: "Vibecoding",
    founded: "2024",
    headquarters: "Open Source",
    descriptionLong: "Vibe Coding is a term popularized by Andrej Karpathy that describes a new paradigm in software development where developers describe what they want in natural language and let AI coding assistants generate, modify, and debug the code. Instead of writing code line by line, the developer provides high-level descriptions and the AI handles the implementation across HTML, CSS, JavaScript, database queries, and API calls. The developer role shifts from writing code to reviewing, providing feedback, guiding the AI through iterations, and making architectural decisions. Vibe Coding represents a fundamental shift from being the primary creator to being a director who guides AI executors. It emphasizes speed and iteration: you can try different approaches quickly, ask the AI to rewrite sections with different patterns, and explore architectural alternatives without manual implementation cost. For experienced developers, Vibe Coding dramatically accelerates prototyping and reduces boilerplate writing. For beginners, it lowers the barrier to creating functional applications by focusing on ideas rather than syntax. Tools like Cursor, Copilot, Claude Code, Bolt.new, and Lovable are designed for Vibe Coding workflows. While Vibe Coding is a methodology rather than a specific tool, understanding this paradigm helps developers get the most out of AI coding assistants by shifting focus from how to code it to what to build. The approach works best for web applications, scripts, and prototypes where speed matters more than absolute code quality.\"vibe\" or direction rather than the technical details. Instead of writing code line by line, the developer provides high-level descriptions: \"create a responsive dashboard with dark mode, real-time data updates, and three chart types\", and the AI handles the implementation across HTML, CSS, JavaScript, database queries, and API calls. The developer's role shifts from writing code to reviewing, providing feedback, guiding the AI through iterations, and making architectural decisions. Vibe Coding represents a fundamental shift in the developer's relationship with code — from being the primary creator to being a director who guides AI executors. It emphasizes speed and iteration: you can try different approaches quickly, ask the AI to rewrite sections with different patterns, and explore architectural alternatives without the cost of manual implementation. For experienced developers, Vibe Coding dramatically accelerates prototyping and reduces boilerplate writing. For beginners, it lowers the barrier to creating functional applications by focusing on ideas rather than syntax. Tools like Cursor, Copilot, Bolt.new, and Lovable are designed for Vibe Coding workflows. While Vibe Coding isn't a tool itself, it represents the methodology that drives the current generation of AI-first development tools — understanding this paradigm helps developers get the most out of AI coding assistants by shifting their focus from \"how to code it\" to \"what to build.\"",
    descriptionLongZh: "Vibe Coding 是由 Andrej Karpathy 推广的一个术语，描述了一种新的软件开发范式：开发者用自然语言描述他们想要的内容，让 AI 编码助手生成、修改和调试代码。开发者从逐行编写代码转变为提供高层次描述，AI 处理 HTML、CSS、JavaScript、数据库查询和 API 调用的实现。开发者的角色从代码的主要创建者转变为指导 AI 执行者的导演。Vibe Coding 强调速度和迭代：你可以快速尝试不同方法，探索架构替代方案而无需手动实现成本。对于经验丰富的开发者来说，Vibe Coding 大大加速了原型设计。对于初学者来说，通过关注创意而非语法来降低创建功能应用的门槛。Cursor、Copilot、Claude Code、Bolt.new 和 Lovable 等工具都是为 Vibe Coding 工作流设计的。理解这种范式有助于开发者通过将焦点从如何编码转移到构建什么来最大限度地利用 AI 编码助手。\"氛围\"或方向而非技术细节。开发者从逐行编写代码转变为提供高层次描述。开发者的角色从代码的主要创建者转变为指导 AI 执行者的导演。Vibe Coding 强调速度和迭代：你可以快速尝试不同方法，要求 AI 用不同模式重写部分内容，探索架构替代方案而无需手动实现的成本。对于经验丰富的开发者来说，Vibe Coding 大大加速了原型设计并减少了样板代码编写。对于初学者来说，通过关注创意而非语法来降低创建功能应用的门槛。虽然 Vibe Coding 本身不是工具，但它代表了驱动当前一代 AI 优先开发工具的方法论——理解这种范式有助于开发者通过将焦点从\"如何编码\"转移到\"构建什么\"来最大限度地利用 AI 编码助手。",
