    pricingTiers: [{tier: "Open Source", tierZh: "开源版", price: "$0", features: ["Full OTel SDK", "Auto-instrumentation", "All exporters", "Apache 2.0"], featuresZh: ["完整OTel SDK", "自动检测", "全部导出器", "Apache 2.0"]}],
