    headquarters: "Remote",
    descriptionLong: "Unsloth is an open-source library that dramatically improves the efficiency of LLM fine-tuning by implementing custom CUDA kernels and memory optimizations. It achieves 2x faster training speeds and up to 70% memory reduction compared to standard Hugging Face Transformers, without any accuracy degradation. Unsloth supports popular models including Llama, Mistral, Qwen, Gemma, and Phi families, and integrates seamlessly with LoRA (Low-Rank Adaptation) and QLoRA for parameter-efficient fine-tuning. The library works with both single-GPU setups (even consumer cards like RTX 3060) and multi-GPU clusters, making advanced AI model customization accessible to individual developers. Unsloth also provides a free Colab notebook for one-click fine-tuning, pre-optimized datasets, and a growing community of practitioners sharing fine-tuned models.",
    descriptionLongZh: "Unsloth 是一个开源库，通过实现自定义 CUDA 内核和内存优化，大幅提升 LLM 微调效率。相比标准 Hugging Face Transformers，它实现 2 倍训练速度和高达 70% 内存减少，且无精度损失。Unsloth 支持 Llama、Mistral、Qwen、Gemma、Phi 等主流模型，并与 LoRA 和 QLoRA 无缝集成，实现参数高效微调。该库支持单 GPU 设置（甚至 RTX 3060 等消费级显卡）和多 GPU 集群，使高级 AI 模型定制对个人开发者也可及。Unsloth 还提供免费的 Colab 笔记本一键微调、预优化数据集和不断增长的微调模型社区。",
