    descriptionLong: "Qwen (Tongyi Qianwen) is Alibaba's family of large language models that has consistently ranked among the top open-source models globally. Available in sizes from 0.5B to 72B parameters, Qwen models excel at multilingual understanding (particularly Chinese and English), code generation, mathematical reasoning, and serve as excellent base models for fine-tuning. The Qwen 3.5 series introduced significant improvements in instruction following, tool use, and long-context handling (up to 128K tokens). For developers, Qwen's key advantage is its permissive Apache 2.0 license and the availability of small, efficient variants (1.5B, 3B, 4B) that can be fine-tuned on consumer hardware and deployed on edge devices.",
    descriptionLongZh: "Qwen（通义千问）是阿里巴巴的大语言模型系列，始终位列全球顶级开源模型。Qwen 提供从 0.5B 到 72B 参数的多种规模，擅长多语言理解（尤其是中英文）、代码生成、数学推理，是优秀的微调基座模型。Qwen 3.5 系列在指令遵循、工具使用和长上下文处理（最高 128K tokens）方面有显著提升。对开发者而言，Qwen 的关键优势是宽松的 Apache 2.0 许可证和高效小型变体（1.5B、3B、4B）的可用性，可在消费级硬件上微调并部署到边缘设备。",
