    headquarters: "San Francisco, CA",
    descriptionLong: "OpenAI Codex CLI is an open-source terminal-based AI agent designed for autonomous software engineering tasks. Unlike traditional copilot tools that suggest code inline, Codex operates as a full agent: it reads your entire codebase, understands the task, writes code across multiple files, runs tests, checks for errors, and iterates until the work is complete. Codex uses a planning-execution-verification loop. It integrates with the terminal, file system, and git, making it capable of end-to-end development workflows. The CLI is model-agnostic and works with GPT-5, Claude, and other LLM backends. Combined with Harness Engineering principles, Codex becomes the execution engine in an AI-powered development pipeline.",
    descriptionLongZh: "OpenAI Codex CLI 是一个开源的终端 AI 代理，专为自主软件工程任务设计。与传统的在代码行内建议的内联补全工具不同，Codex 作为完整的代理运行：它读取整个代码库，理解任务，跨多个文件编写代码，运行测试，检查错误，并迭代直到工作完成。Codex 使用规划-执行-验证循环。它与终端、文件系统和 git 集成，能够完成端到端开发工作流。该 CLI 与模型无关，可与 GPT-5、Claude 及其他 LLM 后端配合使用。结合 Harness Engineering 原则，Codex 成为 AI 驱动开发管道中的执行引擎。",
