    descriptionLong: "Supabase is an open-source Firebase alternative that provides a complete backend platform built on PostgreSQL. It includes a real-time database with row-level security, built-in authentication supporting email/password, OAuth, and magic links, file storage with automatic CDN delivery, and Edge Functions for serverless API endpoints. Unlike Firebase, Supabase uses SQL (Postgres) rather than NoSQL, giving developers the full power of relational queries, joins, and migrations. For AI-powered app development, Supabase is particularly valuable — its Edge Functions can invoke AI APIs (like OpenAI's image generation), its Postgres database handles structured user data and points systems, and its storage bucket serves AI-generated assets. Combined with Expo/React Native for the frontend, Supabase provides the complete backend infrastructure needed to launch an AI app on the App Store.",
    descriptionLongZh: "Supabase 是开源的 Firebase 替代方案，提供基于 PostgreSQL 构建的完整后端平台。它包括具有行级安全性的实时数据库、支持邮箱/密码、OAuth 和魔法链接的内置身份认证、自动 CDN 分发的文件存储，以及用于无服务器 API 端点的 Edge Functions。与 Firebase 不同，Supabase 使用 SQL（Postgres）而非 NoSQL，为开发者提供关系查询、连接和迁移的全部能力。对于 AI 驱动的应用开发，Supabase 特别有价值——其 Edge Functions 可以调用 AI API（如 OpenAI 的图像生成），其 Postgres 数据库处理结构化用户数据和积分系统，其存储桶提供 AI 生成的资产。结合 Expo/React Native 前端，Supabase 提供将 AI 应用发布到 App Store 所需的完整后端基础设施。",
