    descriptionLong: "Expo is the most popular React Native framework that dramatically simplifies cross-platform mobile development. It provides a managed workflow where developers write JavaScript/TypeScript and Expo handles native build configuration, eliminating the need to touch Xcode or Android Studio for most use cases. Key features include Expo Go for instant preview on physical devices, OTA (over-the-air) updates that let you push fixes without App Store review, EAS Build for cloud-based native builds, and EAS Submit for one-command App Store submission. For AI-powered apps, Expo is the ideal frontend framework — AI coding agents like Codex can generate complete Expo/React Native projects that run immediately in Expo Go, integrate with Supabase for backend services, and use Expo's ImagePicker/ImageManipulator for AI image workflows. Combined with Codex's Build iOS Apps plugin for simulator preview, Expo creates the fastest path from AI-generated code to App Store launch.",
    descriptionLongZh: "Expo 是最流行的 React Native 框架，极大地简化了跨平台移动开发。它提供托管工作流，开发者编写 JavaScript/TypeScript，Expo 处理原生构建配置，大多数场景无需接触 Xcode 或 Android Studio。关键功能包括用于在实体设备上即时预览的 Expo Go、无需 App Store 审核即可推送修复的 OTA 更新、用于云端原生构建的 EAS Build，以及一键提交 App Store 的 EAS Submit。对于 AI 驱动的应用，Expo 是理想的前端框架——Codex 等 AI 编码代理可以生成完整的 Expo/React Native 项目，在 Expo Go 中立即可运行，与 Supabase 集成用于后端服务，并使用 Expo 的 ImagePicker/ImageManipulator 进行 AI 图像工作流。结合 Codex 的 Build iOS Apps 插件进行模拟器预览，Expo 创造了从 AI 生成代码到 App Store 发布的最快路径。",
