    descriptionLongZh: "React Native 是 Meta 的开源框架，使用 React 和 JavaScript/TypeScript 构建原生移动应用。与基于 Web 的混合方案不同，React Native 渲染真正的原生 UI 组件，提供与 Swift 或 Kotlin 构建的应用无差别的性能。它为数千个生产应用提供动力，包括 Instagram、Shopify、Discord 和 Coinbase。对于 AI 驱动开发，React Native（尤其是通过 Expo）已成为 AI 编码代理生成移动应用的默认目标——其组件模型与 AI 代码生成清晰映射，庞大的生态提供常见需求的预构建解决方案，单一代码库意味着 AI 可以生成一个同时适用于 iOS 和 Android 的项目。React Native 的热重载和 Fast Refresh 功能也使 AI-人工协作高效，AI 生成的更改可以即时预览。",
